fun processOrder(order: Order) {
    fun validate() = order.items.isNotEmpty() && order.total > 0
    if (!validate()) throw IllegalArgumentException("Invalid order")
}

infix fun Int.pow(exponent: Int): Int {
    var result = 1
    repeat(exponent) { result *= this }
    return result
}
